document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("ovdp-form"),t=document.getElementById("ovdp-result");e.addEventListener("submit",function(n){n.preventDefault();const a=parseFloat(e.price.value),o=new Date(e.nextDate.value),d=parseFloat(e.nextCoupon.value),r=new Date(e.finalDate.value),u=new Date;if(isNaN(a)||isNaN(d)||!o||!r||o<=u||r<=u)return t.innerHTML="Будь ласка, перевірте введені дані.",void 0;const i=[],s=new Date(o);for(;s<r;)i.push({date:new Date(s),amount:d}),s.setMonth(s.getMonth()+6);i.push({date:new Date(r),amount:d});const l=i.length,b=l*d+1e3-a,c=b/a,p=c/((r-u)/864e5/365),v=e=>(100*e).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g," ")+" %";var D;t.innerHTML=`\n      <b>Кількість купонів:</b> ${l}<br>\n      <b>Загальний прибуток:</b> ${D=b,D.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g," ")} грн<br>\n      <b>Загальна дохідність:</b> ${v(c)}<br>\n      <b>Річна дохідність:</b> ${v(p)}\n    `})});